WITH cleaned AS (SELECT *, ROUND(amount, 0) AS amount_rounded, DAYOFWEEK(paid_at) AS paid_at_dayofweek FROM payments WHERE order_id IS NOT NULL AND status NOT IN ('SUCCESS', 'FAILED')) SELECT * FROM (SELECT status, order_id, method, paid_at_dayofweek FROM cleaned) src PIVOT (AVG(paid_at_dayofweek) AS value_sum FOR method IN ('paypal' AS paypal, 'bank_transfer' AS bank_transfer, 'card' AS card));
